// Subprocess helpers for andesim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDESIM_PROCESS_HPP
#define ANDESIM_PROCESS_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// and stderr are redirected to /dev/null. If the child runs longer than
// timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms);

}  // namespace andes_sim

#endif  // ANDESIM_PROCESS_HPP
#include "process.hpp"

#include <cerrno>
#include <ctime>

#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <sys/wait.h>
#include <unistd.h>

namespace andes_sim {
namespace {

long now_ms() {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;
}

}  // namespace

RunResult run_process(const std::vector<std::string>& argv, int timeout_ms) {
  RunResult r;
  if (argv.empty()) {
    r.spawn_failed = true;
    return r;
  }

  int fds[2];
  if (pipe(fds) != 0) {
    r.spawn_failed = true;
    return r;
  }

  pid_t pid = fork();
  if (pid < 0) {
    close(fds[0]);
    close(fds[1]);
    r.spawn_failed = true;
    return r;
  }

  if (pid == 0) {  // child
    close(fds[0]);
    dup2(fds[1], STDOUT_FILENO);
    int devnull = open("/dev/null", O_RDWR);
    if (devnull >= 0) {
      dup2(devnull, STDIN_FILENO);
      dup2(devnull, STDERR_FILENO);
      if (devnull > 2) close(devnull);
    }
    close(fds[1]);
    std::vector<char*> cargv;
    cargv.reserve(argv.size() + 1);
    for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
    cargv.push_back(nullptr);
    execvp(cargv[0], cargv.data());
    _exit(127);  // exec failed
  }

  // parent
  close(fds[1]);
  int rfd = fds[0];
  const long deadline = now_ms() + timeout_ms;
  char buf[4096];

  while (true) {
    long remaining = deadline - now_ms();
    if (remaining < 0) remaining = 0;
    struct pollfd pfd{rfd, POLLIN, 0};
    int pr = poll(&pfd, 1, static_cast<int>(remaining));
    if (pr < 0) {
      if (errno == EINTR) continue;
      break;
    }
    if (pr == 0) {  // timed out with no data ready
      kill(pid, SIGKILL);
      r.timed_out = true;
      break;
    }
    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
      ssize_t n = read(rfd, buf, sizeof(buf));
      if (n > 0) {
        r.out.append(buf, static_cast<size_t>(n));
      } else if (n == 0) {
        break;  // EOF: child closed stdout
      } else {
        if (errno == EINTR) continue;
        break;
      }
    }
    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
      kill(pid, SIGKILL);
      r.timed_out = true;
      break;
    }
  }

  close(rfd);
  int status = 0;
  waitpid(pid, &status, 0);
  // rc stays -1 (the default) when timed out or abnormally terminated.
  if (!r.timed_out && WIFEXITED(status)) r.rc = WEXITSTATUS(status);
  return r;
}

}  // namespace andes_sim

